const item = $input.first();
const binary = item.binary?.data;

if (!binary) {
  return [{ json: { ...item.json, file_type: 'unsupported', original_filename: item.json.name || 'unknown' }, pairedItem: { item: 0 } }];
}

const fileName = binary.fileName || item.json.name || 'unknown';
const mimeType = (binary.mimeType || '').toLowerCase();
const ext = (fileName.split('.').pop() || '').toLowerCase();

let file_type = 'unsupported';
if (ext === 'pdf' || mimeType === 'application/pdf') {
  file_type = 'pdf';
} else if (ext === 'docx' || mimeType.includes('officedocument.wordprocessingml')) {
  file_type = 'docx';
} else if (ext === 'doc' || mimeType === 'application/msword') {
  file_type = 'doc';
} else if (ext === 'txt' || mimeType.startsWith('text/plain')) {
  file_type = 'txt';
}

return [{
  json: { ...item.json, file_type, original_filename: fileName },
  binary: item.binary,
  pairedItem: { item: 0 }
}];

const item = $input.first();
const { text: rawText, ...rest } = item.json;
const text = (rawText || '').trim();

let extractedLinks = [];
try {
  const zlib = require('zlib');
  const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (pdfBuffer && pdfBuffer.length > 0) {
    const raw = pdfBuffer.toString('latin1');
    const chunks = [raw];
    const streamRegex = /stream\r?\n([\s\S]*?)endstream/g;
    let sm;
    while ((sm = streamRegex.exec(raw)) !== null) {
      try {
        const compressed = Buffer.from(sm[1], 'latin1');
        const inflated = zlib.inflateSync(compressed).toString('latin1');
        chunks.push(inflated);
      } catch (e) {}
    }
    const seen = new Set();
    const uriRegex = /\/URI\s*\(([^)]+)\)/g;
    for (const chunk of chunks) {
      let m;
      while ((m = uriRegex.exec(chunk)) !== null) {
        let url = m[1].replace(/\\([()\\])/g, '$1').trim();
        if (url && url.startsWith('http') && !seen.has(url)) {
          seen.add(url);
          extractedLinks.push({ text: url, url });
        }
      }
      const hexRegex = /\/URI\s*<([0-9A-Fa-f]+)>/g;
      while ((m = hexRegex.exec(chunk)) !== null) {
        let url = '';
        for (let i = 0; i < m[1].length; i += 2) {
          url += String.fromCharCode(parseInt(m[1].substr(i, 2), 16));
        }
        url = url.trim();
        if (url && url.startsWith('http') && !seen.has(url)) {
          seen.add(url);
          extractedLinks.push({ text: url, url });
        }
      }
    }
  }
} catch (linkErr) {}

return [{
  json: { ...rest, raw_text: text, is_scanned: text.length < 100, extracted_links: extractedLinks },
  binary: $('Detect File Type').item.binary
}];

const zlib = require('zlib');
const item = $input.first();
const buffer = Buffer.from(item.binary.data.data, 'base64');

function readZipEntry(buf, entryName) {
  const eocdSig = 0x06054b50;
  let eocdOffset = -1;
  for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === eocdSig) { eocdOffset = i; break; }
  }
  if (eocdOffset === -1) throw new Error('Not a valid DOCX (zip) file');

  const cdEntries = buf.readUInt16LE(eocdOffset + 10);
  let offset = buf.readUInt32LE(eocdOffset + 16);

  for (let i = 0; i < cdEntries; i++) {
    if (buf.readUInt32LE(offset) !== 0x02014b50) break;
    const compMethod = buf.readUInt16LE(offset + 10);
    const compSize = buf.readUInt32LE(offset + 20);
    const nameLen = buf.readUInt16LE(offset + 28);
    const extraLen = buf.readUInt16LE(offset + 30);
    const commentLen = buf.readUInt16LE(offset + 32);
    const localHeaderOffset = buf.readUInt32LE(offset + 42);
    const fileName = buf.toString('utf8', offset + 46, offset + 46 + nameLen);

    if (fileName === entryName) {
      const lfhNameLen = buf.readUInt16LE(localHeaderOffset + 26);
      const lfhExtraLen = buf.readUInt16LE(localHeaderOffset + 28);
      const dataStart = localHeaderOffset + 30 + lfhNameLen + lfhExtraLen;
      const compData = buf.subarray(dataStart, dataStart + compSize);
      return compMethod === 0 ? compData : zlib.inflateRawSync(compData);
    }

    offset += 46 + nameLen + extraLen + commentLen;
  }
  throw new Error(`Entry ${entryName} not found in DOCX`);
}

const xml = readZipEntry(buffer, 'word/document.xml').toString('utf8');

const text = xml
  .replace(/<\/w:p>/g, '\n')
  .replace(/<w:tab\s*\/>/g, '\t')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&apos;/g, "'")
  .trim();

return [{ json: { ...item.json, raw_text: text } }];

const item = $input.first();
const raw_text = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');

return [{ json: { ...item.json, raw_text } }];

const item = $input.first();
return [{
  json: {
    ...item.json,
    extraction_error: 'DOC (legacy binary Word) format requires LibreOffice conversion on the n8n host, which is not yet configured. Convert this file to .docx or .pdf and re-upload, or configure an Execute Command node running "libreoffice --headless --convert-to docx" and route its output into the DOCX extraction branch.'
  }
}];

const item = $input.first();
return [{
  json: {
    ...item.json,
    extraction_error: `Unsupported file type for "${item.json.original_filename || 'unknown file'}". Supported types: pdf, docx, doc, txt.`
  }
}];

const item = $input.first();
const response = item.json;
let text = '';

if (response.output_text) {
  text = response.output_text;
} else if (Array.isArray(response.output)) {
  for (const block of response.output) {
    if (Array.isArray(block.content)) {
      for (const c of block.content) {
        if (c.type === 'output_text' && c.text) text += c.text;
      }
    }
  }
}

let rawText = text.trim();
let visionLinks = [];
const sep = rawText.indexOf('---LINKS---');
if (sep !== -1) {
  const jsonPart = rawText.slice(sep + 11).trim();
  rawText = rawText.slice(0, sep).trim();
  try {
    const parsed = JSON.parse(jsonPart);
    if (Array.isArray(parsed)) {
      visionLinks = parsed.filter(l => l && l.text);
    }
  } catch (e) {}
}

const pdfLinks = $('Convert PDF to PNG').first().json.extracted_links || [];
const merged = [...pdfLinks];
const seen = new Set(pdfLinks.map(l => l.url || l.text));
for (const vl of visionLinks) {
  const key = vl.url || vl.text;
  if (!seen.has(key)) {
    seen.add(key);
    merged.push(vl);
  }
}

return [{
  json: {
    ...$('Detect File Type').first().json,
    raw_text: rawText,
    extracted_links: merged
  }
}];

return $input.all().map(item => {
  const choice = item.json.choices?.[0];
  const content = choice?.message?.content;

if (!content) {
  throw new Error('Strip chrome stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

if (choice.finish_reason === 'length') {
  throw new Error('Strip chrome stage output was truncated at the model\'s token limit — document too long for single-pass strip.');
}

  return { json: { raw_text: content } };
});

return $input.all().map(item => {
  const content = item.json.choices?.[0]?.message?.content;
  if (!content) {
    throw new Error('Clean stage returned no content: ' + JSON.stringify(item.json).slice(0, 500));
  }
  return { json: { cleaned_text: content } };
});

const item = $input.first();
const content = item.json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Classify stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

let classification;
try {
  classification = JSON.parse(content);
} catch (e) {
  throw new Error(`Classify stage returned invalid JSON: ${e.message}. Content: ${content.slice(0, 500)}`);
}

const required = ['document_type', 'condition', 'topics', 'audience', 'has_patient_triage', 'has_clinician_procedure', 'notes'];
for (const key of required) {
  if (!(key in classification)) {
    throw new Error(`Classification JSON missing required field: ${key}`);
  }
}

return [{ json: classification }];

const item = $input.first();
const md = item.json.choices?.[0]?.message?.content;

if (!md) {
  throw new Error('Produce KB stage returned no content. Response: ' + JSON.stringify(item.json).slice(0, 500));
}

const docsRur = $('Get Enrich Record').first().json.fields.docs_rur || '';
const fallbackName = ($('Detect File Type').first().json.original_filename || 'document').replace(/\.[^.]+$/, '');
const baseName = (docsRur || fallbackName)
  .replace(/[^a-zA-Z0-9 _-]/g, '')
  .trim()
  .replace(/\s+/g, '-');

return [{
  json: {
    kb_markdown: md,
    output_filename: `${baseName}.md`
  }
}];

const item = $input.first();
const j = item.json || {};

const errorMessage = j.error?.message || j.message || j.extraction_error || JSON.stringify(j).slice(0, 1000);

let filename = 'unknown';
try {
  filename = $('Detect File Type').first()?.json?.original_filename || filename;
} catch (_) {}

if (filename === 'unknown') {
  try {
    const dl = $('Download File').first();
    filename = dl?.binary?.data?.fileName || dl?.json?.name || filename;
  } catch (_) {}
}

return [{
  json: {
    error_log: JSON.stringify({
      original_filename: filename,
      error_message: errorMessage,
      timestamp: new Date().toISOString()
    }, null, 2),
    error_filename: `${filename}.error.json`
  }
}];

const { execSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const item = $input.first();
const binary = item.binary?.data;

if (!binary) {
  throw new Error('No binary data found — cannot convert PDF to PNG');
}

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'pdf2png-'));
const pdfPath = path.join(tmpDir, 'input.pdf');
const pngPrefix = path.join(tmpDir, 'page');

try {
  const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  fs.writeFileSync(pdfPath, pdfBuffer);

  execSync(`pdftoppm -png -r 300 "${pdfPath}" "${pngPrefix}"`, {
    timeout: 60000,
    maxBuffer: 100 * 1024 * 1024
  });

  const pngFiles = fs.readdirSync(tmpDir)
    .filter(f => f.startsWith('page-') && f.endsWith('.png'))
    .sort();

  if (pngFiles.length === 0) {
    throw new Error('pdftoppm produced no PNG files — check that poppler-utils is installed');
  }

  const pageImages = pngFiles.map((file, index) => {
    const pngBuffer = fs.readFileSync(path.join(tmpDir, file));
    return {
      page: index + 1,
      data_url: 'data:image/png;base64,' + pngBuffer.toString('base64')
    };
  });

  let extractedLinks = [];
  try {
    const zlib = require('zlib');
    const raw = pdfBuffer.toString('latin1');
    const chunks = [raw];
    const streamRegex = /stream\r?\n([\s\S]*?)endstream/g;
    let sm;
    while ((sm = streamRegex.exec(raw)) !== null) {
      try {
        const compressed = Buffer.from(sm[1], 'latin1');
        const inflated = zlib.inflateSync(compressed).toString('latin1');
        chunks.push(inflated);
      } catch (e) {}
    }
    const seen = new Set();
    const uriRegex = /\/URI\s*\(([^)]+)\)/g;
    for (const chunk of chunks) {
      let m;
      while ((m = uriRegex.exec(chunk)) !== null) {
        let url = m[1].replace(/\\([()\\])/g, '$1').trim();
        if (url && url.startsWith('http') && !seen.has(url)) {
          seen.add(url);
          extractedLinks.push({ text: url, url });
        }
      }
      const hexRegex = /\/URI\s*<([0-9A-Fa-f]+)>/g;
      while ((m = hexRegex.exec(chunk)) !== null) {
        let url = '';
        for (let i = 0; i < m[1].length; i += 2) {
          url += String.fromCharCode(parseInt(m[1].substr(i, 2), 16));
        }
        url = url.trim();
        if (url && url.startsWith('http') && !seen.has(url)) {
          seen.add(url);
          extractedLinks.push({ text: url, url });
        }
      }
    }
  } catch (linkErr) {}

  return [{
    json: {
      ...item.json,
      page_images: pageImages,
      page_count: pageImages.length,
      extracted_links: extractedLinks
    }
  }];

} finally {
  try {
    const files = fs.readdirSync(tmpDir);
    for (const file of files) {
      fs.unlinkSync(path.join(tmpDir, file));
    }
    fs.rmdirSync(tmpDir);
  } catch (e) {}
}

const item = $input.first();
const text = item.json.raw_text || '';
const CHUNK_SIZE = 60000;

if (text.length <= CHUNK_SIZE) {
  return [item];
}

const paragraphs = text.split(/\n\n+/);
const chunks = [];
let current = '';

for (const para of paragraphs) {
  if (current.length + para.length + 2 > CHUNK_SIZE && current.length > 0) {
    chunks.push(current);
    current = para;
  } else {
    current = current ? current + '\n\n' + para : para;
  }
}
if (current) chunks.push(current);

return chunks.map((chunk) => ({
  json: { ...item.json, raw_text: chunk }
}));

const items = $input.all();
const combined = items.map(i => i.json.cleaned_text).join('\n\n');
return [{ json: { cleaned_text: combined } }];
